sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float strength;
uniform float curve;
uniform float rotate;
uniform float2 anchor;
uniform float transparentEdge;
uniform float opacity;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float4 texT(float2 p) {
    return float4(image.eval(p));
}
float4 smp(float2 p, float tr) {
    return tr > 0.5 ? texT(p) : tex(p);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float e = pow(saturate(beat), curve);
    float2 anc = anchor * size;
    float2 q = anc + rot2(coord - anc, -radians(rotate) * e) / (1.0 + e * strength);
    return fin(c, smp(q, transparentEdge), opacity);
}
